INSERT INTO services(category_id,service_code,service_name,description,short_description,service_type,price_unit,base_price,estimated_duration_minutes,image_url,highlights,workflow,benefits) SELECT c.id,'UI-srv-001','Vệ sinh nhà theo giờ','Dọn dẹp phòng khách, phòng ngủ, nhà bếp, nhà tắm theo gói thời gian linh hoạt (2 - 4 giờ).','Linh hoạt 2 - 4h, tự chọn nhân viên hoặc khớp lệnh tự động nhanh','CLEANING_HOURLY','HOUR',80000,120,'https://images.unsplash.com/photo-1581578731548-c64695cc6952?w=600&auto=format&fit=crop&q=80','["Nhân viên lý lịch rõ ràng","Hỗ trợ Mode A & B","Bảo hiểm hư hại"]'::jsonb,'["Nhận bàn giao khu vực cần dọn dẹp từ chủ nhà","Thu gom rác và sắp xếp đồ đạc bề mặt ngăn nắp","Hút bụi, quét bụi trần nhà, gầm giường, kệ tủ","Lau khử khuẩn bề mặt bàn ghế, thiết bị nhà bếp và WC","Lau sàn lần cuối bằng tinh dầu thiên nhiên và nghiệm thu"]'::jsonb,'["Nhân viên đã xác thực danh tính & lý lịch tư pháp số 2","Được đào tạo kỹ năng dọn dẹp, phân loại rác và bảo quản đồ dùng gia đình","Được trang bị dụng cụ và dung dịch tẩy rửa sinh học an toàn cho trẻ nhỏ","Cam kết bồi thường hư hại đồ đạc trong quá trình làm việc"]'::jsonb FROM service_categories c WHERE c.category_code='CLEANING_HOURLY' ON CONFLICT(service_code) DO NOTHING;
