INSERT INTO services(category_id,service_code,service_name,description,short_description,service_type,price_unit,base_price,estimated_duration_minutes,image_url,highlights,workflow,benefits) SELECT c.id,'UI-srv-002','Tổng vệ sinh toàn diện','Làm sạch sâu toàn bộ diện tích nhà ở, căn hộ sau xây dựng, dọn về nhà mới hoặc đón Tết.','Làm sạch sâu sàn, kính, WC, hút bụi công nghiệp trọn gói','CLEANING_DEEP','PACKAGE',700000,240,'https://images.unsplash.com/photo-1497366216548-37526070297c?w=600&auto=format&fit=crop&q=80','["Máy móc công nghiệp","Đội ngũ từ 2 - 4 người","Nghiệm thu từng phòng"]'::jsonb,'["Khảo sát hiện trạng và lập phương án dọn dẹp theo tầng","Xử lý phần thô, quét dọn rác thải kích thước lớn","Hút bụi trần, tường và hệ thống khe cửa","Tẩy cặn canxi kính phòng tắm, đánh bóng thiết bị vệ sinh","Đánh sàn chuyên dụng và lau khô toàn bộ mặt phẳng"]'::jsonb,'["Trang bị máy chà sàn, máy hút bụi công nghiệp chuyên dụng","Tẩy sạch hoàn toàn cặn canxi trên vách kính nhà tắm và vòi inox","Làm sạch sâu trần nhà, khe cửa sổ và các góc khuất khó với","Tùy chọn số lượng nhân viên để bàn giao nhà đúng tiến độ"]'::jsonb FROM service_categories c WHERE c.category_code='CLEANING_DEEP' ON CONFLICT(service_code) DO NOTHING;
