INSERT INTO services(category_id,service_code,service_name,description,short_description,service_type,price_unit,base_price,estimated_duration_minutes,image_url,highlights,workflow,benefits) SELECT c.id,'UI-srv-003','Vệ sinh sofa, nệm & rèm','Giặt phun hút bằng hơi nước nóng nhiệt độ cao, diệt khuẩn 99.9% mạt bụi và nấm mốc.','Công nghệ phun hút hơi nước nóng, diệt khuẩn mạt bụi','CLEANING_UPHOLSTERY','ITEM',250000,90,'https://images.unsplash.com/photo-1555041469-a586c61ea9bc?w=600&auto=format&fit=crop&q=80','["Hơi nước nóng 140°C","Sấy khô nhanh 90 phút","Khử khuẩn mạt bụi"]'::jsonb,'["Hút bụi bề mặt và các khe kẽ của sofa/nệm","Phun dung dịch vệ sinh sinh học thẩm thấu vào sợi vải","Đánh tan vết bám bằng máy xoay bàn chải mềm","Phun hơi nước nóng khử khuẩn sâu","Hút nước bẩn nhiều lần bằng máy hút chân không chuyên dụng"]'::jsonb,'["Hơi nước nóng nhiệt độ cao đánh bay vết bẩn cứng đầu","Dung dịch enzyme sinh học an toàn cho da nhạy cảm và em bé","Hút chân không công suất lớn giúp nệm khô ráo nhanh sau 1-2h"]'::jsonb FROM service_categories c WHERE c.category_code='CLEANING_UPHOLSTERY' ON CONFLICT(service_code) DO NOTHING;
