INSERT INTO services(category_id,service_code,service_name,description,short_description,service_type,price_unit,base_price,estimated_duration_minutes,image_url,highlights,workflow,benefits) SELECT c.id,'UI-srv-004','Vệ sinh máy lạnh','Tháo mặt nạ, xịt rửa dàn lạnh, dàn nóng bằng vòi xịt áp lực cao, khử khuẩn và thông ống nước thải.','Xịt rửa dàn lạnh & dàn nóng, thông ống xả, kiểm tra gas','AC_CLEANING','ITEM',150000,45,'https://images.unsplash.com/photo-1621905251189-08b45d6a269e?w=600&auto=format&fit=crop&q=80','["Thợ có chứng chỉ điện lạnh","Có bạt hứng chống bắn nước","Bảo hành chảy nước 30 ngày"]'::jsonb,'["Kiểm tra tình trạng hoạt động và nhiệt độ gió trước khi làm","Ngắt nguồn điện an toàn, tháo vỏ mặt nạ và lưới lọc bụi","Trùm bạt bảo hộ chuyên dụng cho dàn lạnh","Xịt rửa dàn lạnh bằng máy bơm áp lực, làm sạch quạt lồng sóc","Xịt rửa dàn nóng ngoài trời","Lắp ráp lại, sấy khô bo mạch và vận hành thử nghiệm thu"]'::jsonb,'["Nhân viên mang bạt bọc chuyên dụng hứng nước thải, bảo vệ tường nhà","Vệ sinh kỹ lưỡng cả quạt lồng sóc và máng nước xả","Đo dòng điện và áp suất gas miễn phí trước khi làm","Cam kết bảo hành máy không chảy nước trong 30 ngày"]'::jsonb FROM service_categories c WHERE c.category_code='AC_CLEANING' ON CONFLICT(service_code) DO NOTHING;
INSERT INTO service_packages(service_id,package_name,description,duration_minutes,base_price,max_area) SELECT s.id,'Vệ sinh 1 máy lạnh treo tường (< 2.5 HP)','Xịt rửa dàn lạnh, dàn nóng, thông ống nước xả, kiểm tra gas miễn phí.',45,150000,NULL FROM services s WHERE s.service_code='UI-srv-004' ON CONFLICT(service_id,package_name) DO NOTHING;
