INSERT INTO services(category_id,service_code,service_name,description,short_description,service_type,price_unit,base_price,estimated_duration_minutes,image_url,highlights,workflow,benefits) SELECT c.id,'UI-srv-009','Bảo mẫu & Chăm sóc trẻ em','Trông nom bé tại nhà, cho bé ăn, chơi cùng bé, đọc truyện và hỗ trợ tắm rửa an toàn chu đáo.','Bảo mẫu tận tâm, kiểm tra lý lịch nghiêm ngặt, yêu trẻ','CHILD_CARE','HOUR',120000,240,'https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?w=600&auto=format&fit=crop&q=80','["Kiểm tra lý lịch tư pháp","Chứng chỉ kỹ năng mầm non","Camera giám sát"]'::jsonb,'["Lắng nghe dặn dò thói quen sinh hoạt và ăn uống từ phụ huynh","Vui chơi, đọc sách, hỗ trợ bé phát triển kỹ năng","Cho bé ăn uống theo khẩu phần ba mẹ chuẩn bị sẵn","Tắm rửa, vệ sinh cá nhân và ru bé ngủ đúng giờ","Bàn giao bé và báo cáo các sự việc trong ca làm"]'::jsonb,'["100% nhân viên có lý lịch trong sạch và xác thực sinh trắc học","Được đào tạo kỹ năng sơ cấp cứu cơ bản và tâm lý trẻ em","Thường xuyên cập nhật tình hình ăn ngủ của bé qua ứng dụng"]'::jsonb FROM service_categories c WHERE c.category_code='CHILD_CARE' ON CONFLICT(service_code) DO NOTHING;
