INSERT INTO services(category_id,service_code,service_name,description,short_description,service_type,price_unit,base_price,estimated_duration_minutes,image_url,highlights,workflow,benefits) SELECT c.id,'UI-srv-010','Chăm sóc người cao tuổi','Đồng hành chăm sóc ông bà: hỗ trợ đi lại, ăn uống, nhắc uống thuốc đúng giờ, trò chuyện tinh thần.','Hỗ trợ sinh hoạt, trò chuyện, nhắc lịch uống thuốc, tận tâm','ELDERLY_CARE','HOUR',130000,240,'https://images.unsplash.com/photo-1576765608535-5f04d1e3f289?w=600&auto=format&fit=crop&q=80','["Kiến thức y tế cơ bản","Đo huyết áp & đường huyết","Thấu hiểu tâm lý"]'::jsonb,'["Gặp gỡ thăm hỏi tình trạng sức khỏe của cụ đầu ca","Đo huyết áp, nhiệt độ nếu gia đình yêu cầu","Hỗ trợ vệ sinh cá nhân, ăn uống và nhắc uống thuốc","Dìu cụ đi dạo trong khuôn viên hoặc tập thể dục nhẹ","Ghi chép nhật ký sức khỏe bàn giao cho gia đình"]'::jsonb,'["Nhân viên có chứng chỉ điều dưỡng hoặc kinh nghiệm chăm sóc lâu năm","Biết cách dìu đỡ an toàn, chống ngã cho người già yếu","Trò chuyện sẻ chia giúp các cụ giải tỏa cảm giác cô đơn"]'::jsonb FROM service_categories c WHERE c.category_code='ELDERLY_CARE' ON CONFLICT(service_code) DO NOTHING;
