INSERT INTO services(category_id,service_code,service_name,description,short_description,service_type,price_unit,base_price,estimated_duration_minutes,image_url,highlights,workflow,benefits) SELECT c.id,'DEEP_CLEANING_STANDARD','Tổng vệ sinh','Làm sạch kỹ các khu vực cần chăm chút, lý tưởng trước và sau những dịp đặc biệt.','Nhà cần tổng vệ sinh hoặc làm sạch chuyên sâu','CLEANING_DEEP','PACKAGE',220000,120,'https://images.unsplash.com/photo-1585421514738-01798e348b17?auto=format&fit=crop&w=900&q=85','[]'::jsonb,'["Quét và hút bụi sàn","Lau sàn, vệ sinh bề mặt bàn kệ","Sắp xếp vật dụng theo hướng dẫn","Lau mặt bếp và bồn rửa","Vệ sinh mặt bàn, khu vực dễ bám bẩn","Thu gom rác sinh hoạt","Quét bụi và lau sàn","Gấp chăn, sắp xếp bề mặt","Lau các khu vực dễ bám bụi","Vệ sinh lavabo và gương","Cọ rửa khu vực sàn","Lau các bề mặt trong tầm với"]'::jsonb,'["Giải phóng những giờ dọn dẹp để bạn tập trung cho gia đình và công việc.","Đội ngũ được tuyển chọn và hướng dẫn theo tiêu chuẩn CleanMaster.","Thông tin gói dịch vụ và phạm vi công việc được hiển thị rõ ràng.","Chọn thời lượng, khu vực và add-on phù hợp trên Mobile App."]'::jsonb FROM service_categories c WHERE c.category_code='CLEANING_DEEP' ON CONFLICT(service_code) DO NOTHING;
INSERT INTO service_packages(service_id,package_name,description,duration_minutes,base_price,max_area) SELECT s.id,'Gói 2 giờ','Tập trung điểm cần làm sạch • Phù hợp không gian nhỏ',120,220000,NULL FROM services s WHERE s.service_code='DEEP_CLEANING_STANDARD' ON CONFLICT(service_id,package_name) DO NOTHING;
INSERT INTO service_packages(service_id,package_name,description,duration_minutes,base_price,max_area) SELECT s.id,'Gói 3 giờ','Làm sạch nhiều khu vực • Cân bằng thời gian và phạm vi',180,320000,85 FROM services s WHERE s.service_code='DEEP_CLEANING_STANDARD' ON CONFLICT(service_id,package_name) DO NOTHING;
